//! Generate the TypeScript IPC types from the Rust DTOs.
//!
//! The generated file is checked in so the frontend can import it without a
//! build step. CI regenerates it and fails when the result differs, which keeps
//! the Rust and TypeScript contracts from drifting.
//!
//! Run `cargo test --manifest-path src-tauri/Cargo.toml --lib export_ipc_types`
//! after changing a type that crosses the Tauri IPC boundary.

#[cfg(test)]
mod tests {
    use std::fmt::Write as _;
    use std::path::PathBuf;

    use ts_rs::{Config, TS};

    use crate::commands::{
        AccentColor, AlbumOverview, AppSettings, Appearance, BackupInfo, BatchExportError,
        BatchExportItem, BatchExportProgress, BatchExportRequest, BatchExportResult, CropRect,
        CropState, DefaultLayout, DuplicateGroup, EditPreset, EditRecipe, EditValues, ExifData,
        ExportResult, ExternalPlayer, LibraryFilterDTO, LibraryFolder, LibraryItemsPage,
        LibraryStats, PartialSettings, RenderRequest, RestoreResult, RootPathMappingPreview,
        RootPathMappingResult, ScanResult, SmartAlbum, SmartAlbumFilter, StartupView,
        ThumbnailRequest, ThumbnailResponse, ThumbnailSize, TrashError, TrashResult, UpdateCheck,
        ViewerZoomBehavior,
    };
    use crate::media_kind::MediaKind;
    use crate::models::{Album, MediaItem, Tag};

    fn export_dir() -> PathBuf {
        PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../src/engine/types/generated")
    }

    #[test]
    fn export_ipc_types() {
        // `i64` is a JavaScript `number` for this app: timestamps are
        // milliseconds and file sizes stay below 2^53.
        let config = Config::new().with_large_int("number");

        let mut output = String::from(
            "// This file is generated by `cargo test --lib export_ipc_types`.\n\
             // Do not edit it by hand; change the Rust DTOs instead.\n\n",
        );

        macro_rules! emit {
            ($($ty:ty),* $(,)?) => {
                $(
                    let declaration = <$ty as TS>::decl(&config);
                    writeln!(output, "export {declaration}\n").expect("write generated type");
                )*
            };
        }

        emit!(
            Appearance,
            AccentColor,
            StartupView,
            DefaultLayout,
            ThumbnailSize,
            ViewerZoomBehavior,
            MediaKind,
            MediaItem,
            Album,
            Tag,
            ScanResult,
            LibraryFolder,
            LibraryFilterDTO,
            LibraryItemsPage,
            LibraryStats,
            ThumbnailRequest,
            ThumbnailResponse,
            ExifData,
            RenderRequest,
            EditValues,
            CropRect,
            CropState,
            ExportResult,
            BatchExportRequest,
            BatchExportItem,
            BatchExportProgress,
            BatchExportResult,
            BatchExportError,
            TrashResult,
            TrashError,
            DuplicateGroup,
            SmartAlbumFilter,
            SmartAlbum,
            BackupInfo,
            RestoreResult,
            RootPathMappingPreview,
            RootPathMappingResult,
            AlbumOverview,
            EditRecipe,
            EditPreset,
            ExternalPlayer,
            UpdateCheck,
            AppSettings,
            PartialSettings,
        );

        let directory = export_dir();
        std::fs::create_dir_all(&directory).expect("create generated types directory");
        std::fs::write(directory.join("ipc.ts"), output).expect("write generated IPC types");
    }
}
